using System.Collections.Generic;
using FishNet;
using FishNet.Managing.Client;
using FishNet.Transporting;
using RyanAssets.Characters.Client;
using RyanAssets.GameFeel;
using RyanAssets.Rounds;
using RyanAssets.UI.GameHud;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Universes.UniverseData.capture_the_flag.Client {
    /// <summary>
    /// Shows the score, both flags, power-ups and flag events from server state, with the moments that
    /// go with them (beacons, capture confetti, countdown). Decides nothing. The HUD it drives
    /// (FlagWarsHUD) is generated by CTF_Authoring from the shared HudKit; combat feedback lives in
    /// <see cref="CTF_CombatFeedback"/> and weapon feel in <see cref="CTF_GunFeel"/> on the same prefab.
    /// </summary>
    public sealed class CTF_ClientController : MonoBehaviour {
        [Header("Scoreboard")]
        public TMP_Text redScoreLabel;
        public TMP_Text blueScoreLabel, timerLabel, phaseLabel;
        public HudChip redFlagStatus, blueFlagStatus;

        [Header("Team and objective")]
        public HudPopup teamCard;
        public Image teamDisc;
        public TMP_Text teamLabel;
        public HudPopup objective;
        public Image objectiveDisc, objectiveIcon;
        public TMP_Text objectiveLabel;
        public HudChip objectiveDistance;

        [Header("Events")]
        public HudToastFeed toasts;
        public HudBanner banner;
        public CTF_Waypoints waypoints;

        [Header("Icons")]
        public Sprite flagIcon;
        public Sprite homeIcon, carriedIcon, droppedIcon, attackIcon, defendIcon, victoryIcon, defeatIcon;
        public Sprite healthIcon, speedIcon;

        [Header("Look")]
        [Tooltip("Post-processing mood applied while this game is loaded.")]
        public MoodPreset mood = MoodPreset.ArcadeBright;
        [Min(0f)] public float moodFadeSeconds = 1.5f;
        public CTF_FlagBeacons beacons = new();

        [Header("Moments")]
        [Tooltip("The big 3-2-1 starts when the pre-match countdown reaches this.")]
        [Min(1)] public int bigCountdownFrom = 3;
        public string goText = "FIGHT!";
        [Tooltip("Confetti size: smaller pieces read better than a few big ones.")]
        [Min(0.1f)] public float captureConfettiScale = 1.3f;
        [Tooltip("Where the two capture confetti bursts go, from the scoring team's stand: metres toward the field, up and to each side. High enough to clear the parapets and back wall (and the banner) when seen from the field, and in front of the stand so the scorer sees it falling.")]
        public Vector3 captureConfettiOffset = new(9f, 12f, 6f);
        [Tooltip("Extra bursts for the winners on the Won banner, from the local camera: metres ahead, up and to each side. Wide and low enough to land beside the banner rather than behind it or above the screen.")]
        public Vector3 winConfettiOffset = new(8f, 1.5f, 5f);
        [Min(0.1f)] public float captureRingScale = 4f;
        [Range(0f, 1f)] public float captureShake = 0.3f;
        [Min(0f)] public float captureShakeSeconds = 0.35f;
        [Range(0f, 1f)] public float captureFlashAlpha = 0.3f;
        [Min(0.1f)] public float takenRingScale = 2.5f;
        [Min(0.1f)] public float powerUpFxScale = 1.5f;
        [Range(0f, 1f)] public float speedLines = 0.6f;
        [Tooltip("Centre text size for a power-up (1 = the countdown's size).")]
        [Range(0.1f, 1f)] public float powerUpTextSize = 0.45f;
        [Min(0.1f)] public float powerUpTextSeconds = 1.2f;
        [Min(0.5f)] public float winBannerSeconds = 8f;
        [Min(0.5f)] public float captureBannerSeconds = 3.5f;
        [Min(0.5f)] public float flagToastSeconds = 4f;
        [Min(0.5f)] public float powerUpToastSeconds = 3f;
        [Tooltip("Seconds between state requests while this client has no state or team yet.")]
        [Min(0.5f)] public float stateRequestSeconds = 2f;
        public Color drawColor = new(0.85f, 0.87f, 0.9f);
        public Color healthColor = new(0.35f, 1f, 0.45f);
        public Color speedColor = new(1f, 0.85f, 0.25f);

        [Header("Danger")]
        [Tooltip("Edge vignette while an enemy carries your flag.")]
        public Color dangerColor = new(1f, 0.25f, 0.15f);
        [Range(0f, 1f)] public float dangerStrength = 0.7f;
        [Range(0f, 1f)] public float dangerMaxAlpha = 0.4f;
        [Min(0f)] public float dangerPulsesPerSecond = 1.2f;
        [Min(0.1f)] public float dangerFlashSeconds = 1.2f;

        [Header("Flag placement")]
        [Tooltip("Where a carried flag rides, relative to the carrier (world metres along its up/forward).")]
        public float carriedHeight = 2.1f;
        public float carriedBack = 0.4f;
        [Tooltip("The flag you carry yourself rides this far behind your camera, so it never blocks your own view.")]
        [Min(0f)] public float ownCarriedBack = 1.5f;
        [Range(0.1f, 1f)] public float carriedScale = 0.55f;
        [Min(1f)] public float carriedFollow = 30f;
        [Min(1f)] public float looseFollow = 12f;
        [Tooltip("Farther than this from where it is shown, the flag snaps instead of sliding.")]
        [Min(1f)] public float snapDistance = 20f;

        CTF_Map map;
        ClientManager manager;
        CTF_StateBroadcast state;
        bool hasState, hasTeam, bigCountdownStarted, labelsShown = true;
        CTF_Team myTeam;
        float nextRequest, stateAt, speedLinesUntil;
        readonly CTF_FlagView[] views = new CTF_FlagView[2];
        /// <summary>Names from flag events, so the scoreboard can say who carries a flag.</summary>
        readonly Dictionary<int, string> carrierNames = new();
        readonly Vector3[] shown = new Vector3[2];
        // What the HUD shows now, so text is rebuilt only when it changes (not every frame).
        readonly int[] chipKeys = { -1, -1 };
        readonly int[] labelKeys = { -1, -1 };
        int shownLeft = -1, shownPhase = -1, objectiveKey = -1, shownDistance = -1, shownRed = -1, shownBlue = -1;
        bool dangerOn;

        public bool HasTeam => hasTeam;
        public CTF_Team MyTeam => myTeam;

        void Awake() {
            map = GetComponentInParent<CTF_Map>();
            redScoreLabel.text = blueScoreLabel.text = "0";
            timerLabel.text = "--:--";
            phaseLabel.text = "Waiting";
        }

        void Start() {
            beacons.Init(map.transform);
            for (int i = 0; i < 2; i++) {
                if (map.flagPrefabs[i] == null) continue;
                views[i] = Instantiate(map.flagPrefabs[i], map.flagStands[i].position, Quaternion.identity, map.transform).GetComponent<CTF_FlagView>();
                shown[i] = map.flagStands[i].position;
            }
            MoodVolume.Apply(mood, moodFadeSeconds);
        }

        void OnDestroy() {
            beacons.StopAll();
            MoodVolume.Clear(moodFadeSeconds);
            ScreenFx.SetSpeedLines(0f);
            ScreenFx.CancelCountdown();
            ScreenFx.ClearDanger();
            if (manager == null) return;
            manager.UnregisterBroadcast<CTF_StateBroadcast>(OnState);
            manager.UnregisterBroadcast<CTF_TeamBroadcast>(OnTeam);
            manager.UnregisterBroadcast<CTF_EventBroadcast>(OnEvent);
            manager.UnregisterBroadcast<CTF_PowerUpBroadcast>(OnPowerUp);
            manager.OnClientConnectionState -= OnConnectionState;
        }

        /// <summary>A new connection (for example to a restarted server) starts a new state sequence: forget the old one.</summary>
        void OnConnectionState(ClientConnectionStateArgs args) {
            if (args.ConnectionState != LocalConnectionState.Started) return;
            hasState = false;
            hasTeam = false;
        }

        int MyId => manager != null && manager.Connection != null ? manager.Connection.ClientId : -1;

        void Update() {
            if (manager == null && InstanceFinder.ClientManager != null) {
                manager = InstanceFinder.ClientManager;
                manager.RegisterBroadcast<CTF_StateBroadcast>(OnState);
                manager.RegisterBroadcast<CTF_TeamBroadcast>(OnTeam);
                manager.RegisterBroadcast<CTF_EventBroadcast>(OnEvent);
                manager.RegisterBroadcast<CTF_PowerUpBroadcast>(OnPowerUp);
                manager.OnClientConnectionState += OnConnectionState;
            }
            if (manager != null && manager.Started && (!hasState || !hasTeam) && Time.unscaledTime > nextRequest) {
                nextRequest = Time.unscaledTime + stateRequestSeconds;
                manager.Broadcast(new CTF_StateRequest());
            }
            if (speedLinesUntil > 0f && Time.time >= speedLinesUntil) {
                speedLinesUntil = 0f;
                ScreenFx.SetSpeedLines(0f);
            }
            if (!hasState) return;
            PlaceFlag(0, state.redFlag);
            PlaceFlag(1, state.blueFlag);
            RefreshPowerUps();
            RefreshObjective();
            RefreshWaypoints();
            RefreshDanger();
            bool clock = state.phase is CTF_Phase.Playing or CTF_Phase.Countdown;
            int left = !clock ? -2 : state.phase == CTF_Phase.Playing ? Mathf.Max(0, state.secondsLeft - (int)(Time.unscaledTime - stateAt)) : state.secondsLeft;
            if (left != shownLeft) {
                shownLeft = left;
                timerLabel.text = clock ? RoundFormat.Clock(left) : "--:--";
            }
            if ((int)state.phase != shownPhase) {
                shownPhase = (int)state.phase;
                if (state.phase == CTF_Phase.Playing) phaseLabel.SetText("First to {0}", state.capturesToWin);
                else phaseLabel.text = state.phase switch {
                    CTF_Phase.Countdown => "Get ready",
                    CTF_Phase.Results => "Match over",
                    _ => "Waiting"
                };
                // The title and base signs are for the lobby and countdown; in play they would sit behind the HUD.
                bool labels = state.phase is CTF_Phase.Waiting or CTF_Phase.Countdown;
                if (labels != labelsShown) {
                    labelsShown = labels;
                    foreach (var label in map.lobbyLabels) label.SetActive(labels);
                }
            }
            FlagStatus(0, redFlagStatus, state.redFlag);
            FlagStatus(1, blueFlagStatus, state.blueFlag);
        }

        /// <summary>A beating edge vignette while an enemy carries your flag; a flash when it is taken.</summary>
        void RefreshDanger() {
            bool danger = hasTeam && state.phase == CTF_Phase.Playing && Snap(myTeam).state == CTF_FlagState.Carried;
            if (danger == dangerOn) return;
            dangerOn = danger;
            ScreenFx.SetDanger(danger ? dangerStrength : 0f, dangerColor, dangerMaxAlpha, dangerPulsesPerSecond);
        }

        /// <summary>A key for a flag's shown state: changes exactly when its label or chip text would.</summary>
        static int FlagKey(CTF_FlagSnap snap) => snap.state == CTF_FlagState.Carried ? 3 + Mathf.Max(0, snap.carrierId) : (int)snap.state;

        CTF_FlagSnap Snap(CTF_Team team) => team == CTF_Team.Red ? state.redFlag : state.blueFlag;

        void FlagStatus(int i, HudChip chip, CTF_FlagSnap snap) {
            int key = FlagKey(snap);
            if (key == chipKeys[i]) return;
            chipKeys[i] = key;
            (Sprite icon, string text) = snap.state switch {
                CTF_FlagState.Carried => (carriedIcon, snap.carrierId == MyId ? "You have it" : $"Taken by {CarrierName(snap.carrierId)}"),
                CTF_FlagState.Dropped => (droppedIcon, "Dropped"),
                _ => (homeIcon, "Home"),
            };
            chip.SetIcon(icon);
            chip.Text = text;
        }

        string CarrierName(int clientId) => carrierNames.TryGetValue(clientId, out string name) ? name : "an enemy";

        void PlaceFlag(int i, CTF_FlagSnap snap) {
            var view = views[i];
            if (view == null) return;
            Vector3 target = snap.position;
            Transform carrier = null;
            if (snap.state == CTF_FlagState.Carried) {
                var character = CharacterLookup.ByClientId(snap.carrierId);
                if (character != null) {
                    carrier = character.transform;
                    target = carrier.position + carrier.up * carriedHeight - CarryBack(carrier, snap.carrierId == MyId);
                }
            }
            float follow = snap.state == CTF_FlagState.Carried ? carriedFollow : looseFollow;
            shown[i] = (shown[i] - target).sqrMagnitude > snapDistance * snapDistance ? target : Vector3.Lerp(shown[i], target, 1f - Mathf.Exp(-follow * Time.deltaTime));
            view.transform.position = shown[i];
            view.transform.localScale = Vector3.one * (snap.state == CTF_FlagState.Carried ? carriedScale : 1f);
            var team = (CTF_Team)i;
            if ((int)snap.state != labelKeys[i]) {
                labelKeys[i] = (int)snap.state;
                view.Show(snap.state switch {
                    CTF_FlagState.Carried => "",
                    CTF_FlagState.Dropped => $"<color={CTF_Rules.Hex(team)}>{CTF_Rules.Name(team)} FLAG</color>\n<size=70%>dropped</size>",
                    _ => $"<color={CTF_Rules.Hex(team)}>{CTF_Rules.Name(team)} FLAG</color>"
                }, snap.state == CTF_FlagState.Home);
            }
            // No beacons over the results: the flags are home and the banner has the stage.
            if (state.phase == CTF_Phase.Results) beacons.Stop(i);
            else beacons.Refresh(i, snap.state, shown[i], carrier, CTF_Rules.Color(team));
        }

        /// <summary>
        /// Which way, and how far, a carried flag trails its carrier: your own flag goes behind where
        /// you look (a first-person body does not turn with the camera), anyone else's behind their body.
        /// </summary>
        Vector3 CarryBack(Transform carrier, bool mine) {
            Camera cam = mine ? Camera.main : null;
            if (cam != null) {
                Vector3 look = Vector3.ProjectOnPlane(cam.transform.forward, Vector3.up);
                if (look.sqrMagnitude > 1e-4f) return look.normalized * ownCarriedBack;
            }
            return carrier.forward * carriedBack;
        }

        void RefreshPowerUps() {
            var spots = map.powerUps;
            for (int i = 0; i < spots.Length; i++) spots[i].SetAvailable(CTF_Rules.IsReady(state.powerUpsReady, i));
        }

        void RefreshWaypoints() {
            if (waypoints == null) return;
            bool live = hasTeam && state.phase is CTF_Phase.Playing or CTF_Phase.Countdown;
            bool carrying = false;
            for (int i = 0; i < 2; i++) {
                var team = (CTF_Team)i;
                var snap = Snap(team);
                bool mine = live && snap.state == CTF_FlagState.Carried && snap.carrierId == MyId;
                carrying |= mine;
                // Your own flag only needs a marker once it has left home.
                bool show = live && !mine && (team != myTeam || snap.state != CTF_FlagState.Home);
                Sprite icon = snap.state switch {
                    CTF_FlagState.Carried => carriedIcon,
                    CTF_FlagState.Dropped => droppedIcon,
                    _ => flagIcon
                };
                waypoints.SetFlag(i, show, shown[i], icon, CTF_Rules.Color(team));
            }
            waypoints.SetHome(carrying, carrying ? map.Stand(myTeam) : Vector3.zero, homeIcon, CTF_Rules.Color(myTeam));
        }

        void RefreshObjective() {
            bool show = hasTeam && state.phase is CTF_Phase.Playing or CTF_Phase.Countdown;
            objective.SetVisible(show);
            if (!show) {
                objectiveKey = -1;
                return;
            }
            var enemy = CTF_Rules.Other(myTeam);
            var mine = Snap(myTeam);
            var theirs = Snap(enemy);
            bool carrying = theirs.state == CTF_FlagState.Carried && theirs.carrierId == MyId;
            Vector3? target = state.phase == CTF_Phase.Countdown ? null
                : carrying ? map.Stand(myTeam)
                : mine.state == CTF_FlagState.Carried ? null
                : mine.state == CTF_FlagState.Dropped ? mine.position
                : theirs.state == CTF_FlagState.Carried ? null
                : theirs.position;
            int key = ((((int)state.phase * 2 + (carrying ? 1 : 0)) * 3 + (int)mine.state) * 3 + (int)theirs.state) * 2 + (int)myTeam;
            if (key != objectiveKey) {
                objectiveKey = key;
                ShowObjective(state.phase, carrying, mine.state, theirs.state, enemy);
            }
            bool distance = target.HasValue && LocalPlayer.Character != null;
            objectiveDistance.SetVisible(distance);
            if (!distance) {
                shownDistance = -1;
                return;
            }
            int metres = Mathf.RoundToInt(Vector3.Distance(LocalPlayer.Character.transform.position, target.Value));
            if (metres == shownDistance) return;
            shownDistance = metres;
            objectiveDistance.Text = $"{metres} m";
        }

        void ShowObjective(CTF_Phase phase, bool carrying, CTF_FlagState mine, CTF_FlagState theirs, CTF_Team enemy) {
            string text;
            Sprite icon;
            Color color;
            if (phase == CTF_Phase.Countdown) {
                (text, icon, color) = ("Get ready! Pistol <b>1</b>, dagger <b>2</b>", attackIcon, CTF_Rules.Color(myTeam));
            } else if (carrying) {
                (text, icon, color) = mine == CTF_FlagState.Home
                    ? ("You have the flag! Run it home!", carriedIcon, CTF_Rules.Color(enemy))
                    : ("You have the flag! Yours must be home to score", carriedIcon, CTF_Rules.Color(enemy));
            } else if (mine == CTF_FlagState.Carried) {
                (text, icon, color) = ("Your flag was taken! Stop the carrier!", defendIcon, CTF_Rules.Color(myTeam));
            } else if (mine == CTF_FlagState.Dropped) {
                (text, icon, color) = ("Your flag is down. Touch it to return it!", droppedIcon, CTF_Rules.Color(myTeam));
            } else if (theirs == CTF_FlagState.Carried) {
                (text, icon, color) = ("A teammate has their flag. Cover them!", defendIcon, CTF_Rules.Color(myTeam));
            } else if (theirs == CTF_FlagState.Dropped) {
                (text, icon, color) = ($"The <color={CTF_Rules.Hex(enemy)}>{CTF_Rules.Name(enemy)}</color> flag is down. Grab it!", droppedIcon, CTF_Rules.Color(enemy));
            } else {
                (text, icon, color) = ($"Grab the <color={CTF_Rules.Hex(enemy)}>{CTF_Rules.Name(enemy)}</color> flag from their base!", flagIcon, CTF_Rules.Color(enemy));
            }
            objectiveLabel.text = text;
            objectiveIcon.sprite = icon;
            objectiveDisc.color = color;
        }

        // ---------------------------------------------------------------- broadcasts
        void OnState(CTF_StateBroadcast message, Channel channel) {
            // States are unreliable: a late one must not roll the score or the flags back.
            if (hasState && !CTF_Rules.IsNewer(message.sequence, state.sequence)) return;
            if (message.phase != CTF_Phase.Countdown) bigCountdownStarted = false;
            else if (!bigCountdownStarted && message.secondsLeft <= bigCountdownFrom && message.secondsLeft > 0) {
                bigCountdownStarted = true;
                ScreenFx.Countdown(message.secondsLeft, goText);
            }
            state = message;
            hasState = true;
            stateAt = Time.unscaledTime;
            if (message.redScore != shownRed) redScoreLabel.SetText("{0}", shownRed = message.redScore);
            if (message.blueScore != shownBlue) blueScoreLabel.SetText("{0}", shownBlue = message.blueScore);
        }

        void OnTeam(CTF_TeamBroadcast message, Channel channel) {
            myTeam = message.team;
            hasTeam = true;
            objectiveKey = -1;
            teamLabel.text = myTeam == CTF_Team.Red ? "Red" : "Blue";
            teamLabel.color = Color.Lerp(CTF_Rules.Color(myTeam), Color.white, 0.25f);
            teamDisc.color = CTF_Rules.Color(myTeam);
            teamCard.Show();
        }

        void OnEvent(CTF_EventBroadcast message, Channel channel) {
            string flag = $"<color={CTF_Rules.Hex(message.flag)}>{CTF_Rules.Name(message.flag)}</color> flag";
            bool ours = hasTeam && message.flag == myTeam;
            bool teammate = hasTeam && CTF_Rules.ActorTeam(message.kind, message.flag) == myTeam;
            string who = CTF_Rules.PlayerLabel(message.playerName, message.playerId == MyId, teammate);
            Color flagColor = CTF_Rules.Color(message.flag);
            if (!string.IsNullOrEmpty(message.playerName)) {
                carrierNames[message.playerId] = message.playerName;
                chipKeys[0] = chipKeys[1] = -1;
            }
            switch (message.kind) {
                case CTF_EventKind.Taken:
                    Toast(carriedIcon, flagColor, $"{who} took the {flag}!", ours ? SfxCue.Alarm : SfxCue.Pickup);
                    if (ours) ScreenFx.DangerFlash(dangerColor, dangerFlashSeconds);
                    GameFx.Play(FxKind.ShockwaveRing, map.Stand(message.flag), flagColor, takenRingScale);
                    break;
                case CTF_EventKind.Dropped:
                    Toast(droppedIcon, flagColor, $"{who} dropped the {flag}.", SfxCue.Whoosh);
                    break;
                case CTF_EventKind.Returned:
                    // No player: the flag lay on the ground long enough to go home by itself.
                    bool byItself = message.playerId < 0;
                    Toast(homeIcon, flagColor, byItself ? $"The {flag} went home." : $"{who} returned the {flag}.", SfxCue.Coin);
                    GameFx.Play(FxKind.ShockwaveRing, map.Stand(message.flag), flagColor, takenRingScale);
                    break;
                case CTF_EventKind.Captured:
                    OnCaptured(message, ours, who, flag);
                    break;
                case CTF_EventKind.Won: {
                    bool won = hasTeam && message.flag == myTeam;
                    string team = $"<color={CTF_Rules.Hex(message.flag)}>{CTF_Rules.Name(message.flag)}</color>";
                    banner.Show(won || !hasTeam ? victoryIcon : defeatIcon, CTF_Rules.Color(message.flag),
                        !hasTeam ? $"{CTF_Rules.Name(message.flag)} WINS" : won ? "VICTORY!" : "DEFEAT",
                        $"{team} team wins the match {message.redScore}-{message.blueScore}.", winBannerSeconds);
                    GameSfx.Play(won || !hasTeam ? SfxCue.Win : SfxCue.Lose);
                    Celebrate(message.flag);
                    if (won) ConfettiAhead(CTF_Rules.Color(message.flag));
                    break;
                }
                case CTF_EventKind.Draw:
                    banner.Show(flagIcon, drawColor, "DRAW", $"Time is up at {message.redScore}-{message.blueScore}.", winBannerSeconds);
                    GameSfx.Play(SfxCue.Horn);
                    break;
            }
        }

        void OnCaptured(CTF_EventBroadcast message, bool ours, string who, string flag) {
            // The flag captured is the loser's; the capturing team is the other one.
            var scorer = CTF_Rules.Other(message.flag);
            Color scorerColor = CTF_Rules.Color(scorer);
            string subtitle = ours ? $"{who} captured your flag." : $"{who} captured the {flag}!";
            // The winning capture: the Won banner and celebration follow at once, so this one is a toast only.
            int target = state.capturesToWin > 0 ? state.capturesToWin : CTF_Rules.CapturesToWin;
            if (Mathf.Max(message.redScore, message.blueScore) >= target) {
                toasts.Push(flagIcon, scorerColor, subtitle, flagToastSeconds);
                return;
            }
            banner.Show(flagIcon, scorerColor, ours ? "FLAG LOST" : "FLAG CAPTURED", subtitle, captureBannerSeconds);
            GameSfx.Play(ours ? SfxCue.Alarm : SfxCue.LevelUp);
            Celebrate(scorer);
        }

        /// <summary>Two team-colour confetti bursts in front of the team's stand, a ring on it, a screen flash and a shake.</summary>
        void Celebrate(CTF_Team team) {
            Color color = CTF_Rules.Color(team);
            Vector3 stand = map.Stand(team);
            Vector3 field = map.Stand(CTF_Rules.Other(team)) - stand;
            field.y = 0f;
            field.Normalize();
            Vector3 side = Vector3.Cross(Vector3.up, field);
            Vector3 front = stand + field * captureConfettiOffset.x + Vector3.up * captureConfettiOffset.y;
            GameFx.Play(FxKind.Confetti, front + side * captureConfettiOffset.z, color, captureConfettiScale);
            GameFx.Play(FxKind.Confetti, front - side * captureConfettiOffset.z, color, captureConfettiScale);
            GameFx.Play(FxKind.ShockwaveRing, stand, color, captureRingScale);
            CameraShake.Kick(captureShake, captureShakeSeconds);
            ScreenFx.Flash(new Color(color.r, color.g, color.b, captureFlashAlpha));
        }

        /// <summary>Two confetti bursts just ahead of and above the local camera, wherever the player stands.</summary>
        void ConfettiAhead(Color color) {
            Camera view = Camera.main;
            if (view == null) return;
            Transform eye = view.transform;
            Vector3 ahead = Vector3.ProjectOnPlane(eye.forward, Vector3.up);
            ahead = ahead.sqrMagnitude > 1e-4f ? ahead.normalized : Vector3.forward;
            Vector3 side = Vector3.Cross(Vector3.up, ahead) * winConfettiOffset.z;
            Vector3 at = eye.position + ahead * winConfettiOffset.x + Vector3.up * winConfettiOffset.y;
            GameFx.Play(FxKind.Confetti, at + side, color, captureConfettiScale);
            GameFx.Play(FxKind.Confetti, at - side, color, captureConfettiScale);
        }

        void OnPowerUp(CTF_PowerUpBroadcast message, Channel channel) {
            if (message.index < 0 || message.index >= map.powerUps.Length) return;
            var spot = map.powerUps[message.index];
            spot.SetAvailable(false);
            bool health = message.kind == CTF_PowerUpKind.Health;
            Color color = health ? healthColor : speedColor;
            GameFx.Play(health ? FxKind.Heal : FxKind.ShockwaveRing, spot.Position, color, powerUpFxScale);
            GameSfx.PlayAt(SfxCue.Pickup, spot.Position);
            if (message.playerId != MyId) return;
            ScreenFx.ShowText(health ? "+HEALTH" : "SPEED BOOST", color, powerUpTextSeconds, powerUpTextSize);
            toasts.Push(health ? healthIcon : speedIcon, color, health ? "You patched up." : $"Speed boost for {Mathf.RoundToInt(message.seconds)} s!", powerUpToastSeconds);
            if (!health) {
                ScreenFx.SetSpeedLines(speedLines);
                speedLinesUntil = Time.time + message.seconds;
            }
        }

        void Toast(Sprite icon, Color color, string text, SfxCue cue) {
            toasts.Push(icon, color, text, flagToastSeconds);
            GameSfx.Play(cue);
        }
    }
}
